   "location": "chart title (top)",
   "fact": "Public Service Feedback Share by Category"
  },
  {
   "location": "x-axis labels left to right",
   "fact": "Service Quality, Service Cost, Service Design, Support Access, Service Delivery, Other"
  },
  {
   "location": "data point labels above markers",
   "fact": "41% (Service Quality), 46% (Service Cost), 51% (Service Design), 42% (Support Access), 36% (Service Delivery), 10% (Other)"
